#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n2024-12-31\taoi\t09:00\t10:00\tx\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$t"
out=$(ARCHIVE=$t bash tools/purge-archive --before 2025-01-01) || { echo "purge --before failed"; fail=1; }
[ "$out" = "purged 1 row(s) before 2025-01-01 from $t" ] || { echo "purge output: $out"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] && grep -q 'y$' "$t" || { echo "purge --before kept the wrong rows"; fail=1; }
ARCHIVE=$t bash tools/purge-archive --before 2025/06/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "a malformed date should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "a malformed date deleted rows"; fail=1; }
rm -f "$t"

u=$(mktemp); printf '2025-01-01\taoi\t09:00\t10:00\tz\n2025-01-02\taoi\t09:00\t10:00\ty\n' > "$u"
out=$(ARCHIVE=$u bash tools/purge-archive --before 2025-01-01) || { echo "purge --before on the same date failed"; fail=1; }
[ "$out" = "purged 0 row(s) before 2025-01-01 from $u" ] || { echo "same-date output: $out"; fail=1; }
[ "$(grep -vc '^#' "$u")" = 2 ] || { echo "a row on the given date was deleted"; fail=1; }
ARCHIVE=$u bash tools/purge-archive --before 2025-99-99 >/dev/null 2>&1; [ $? = 2 ] || { echo "a month of 99 should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$u")" = 2 ] || { echo "a month of 99 deleted rows"; fail=1; }
[ "$(bash tools/purge-archive 2>&1)" = "usage: purge-archive --all | --before YYYY-MM-DD" ] || { echo "usage line does not list --before"; fail=1; }
rm -f "$u"; exit $fail

